export const getGetConfigValuesUrl = (params: GetConfigValuesParams,) => {
  const normalizedParams = new URLSearchParams();

  Object.entries(params || {}).forEach(([key, value]) => {
    const explodeParameters = ["keys"];

    if (Array.isArray(value) && explodeParameters.includes(key)) {
      value.forEach((v) => {
        normalizedParams.append(key, v === null ? 'null' : String(v));
      });
      return;
    }


  });

  const stringifiedParams = normalizedParams.toString();

  return stringifiedParams.length > 0 ? `/api/v1/platform/configs/values?${stringifiedParams}` : `/api/v1/platform/configs/values`
}

/**
 * 一次查询返回多个键的值（租户覆盖优先）。页面初始化需要多个参数时用这个，避免多次往返（接口瀑布）
 * @summary 批量取参数值
 */
export const getConfigValues = async (params: GetConfigValuesParams, options?: Parameters<typeof request>[1]): Promise<GetConfigValues200> => {

  return request<GetConfigValues200>(getGetConfigValuesUrl(params),
  {
    ...options,
    method: 'GET'


  }
);}



